mapper.insert:
INSERT  INTO TB_GNRL_MBER
      ( ESNTL_ID
      , MBER_ID
      , MBER_NM
      , PASSWORD
      , PASSWORD_HINT
      , PASSWORD_CNSR
      , IHIDNUM
      , SEXDSTN_CODE
      , ZIP
      , ADRES
      , AREA_NO
      , MBER_STTUS
      , DETAIL_ADRES
      , END_TELNO
      , MBTLNUM
      , GROUP_ID
      , MBER_FXNUM
      , MBER_EMAIL_ADRES
      , MIDDLE_TELNO
      , TELNO
      , OCCP_TY
      , SBSCRB_DE )
VALUES  ( #{uniqId}
        , #{mberId}
        , #{mberNm}
        , #{password}
        , #{passwordHint}
        , #{passwordCnsr}
        , #{ihidnum}
        , #{sexdstnCode}
        , #{zip}
        , #{adres}
        , #{areaNo}
        , #{mberSttus}
        , #{detailAdres}
        , #{endTelno}
        , #{moblphonNo}
        , #{groupId}
        , #{mberFxnum}
        , #{mberEmailAdres}
        , #{middleTelno}
        , #{telno}
        , #{occpTy}
        , now() )

mapper.update:
UPDATE  TB_GNRL_MBER
   SET  MBER_STTUS = 'P'
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_ENTRPRS_MBER
   SET  ENTRPRS_MBER_STTUS = 'P'
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_EMPLYR_INFO
   SET  EMPLYR_STTUS_CODE = 'P'
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_GNRL_MBER
   SET  MBER_ID          = #{mberId}
      , MBER_NM          = #{mberNm}
      , PASSWORD_HINT    = #{passwordHint}
      , PASSWORD_CNSR    = #{passwordCnsr}
      , IHIDNUM          = #{ihidnum}
      , SEXDSTN_CODE     = #{sexdstnCode}
      , ZIP              = #{zip}
      , ADRES            = #{adres}
      , AREA_NO          = #{areaNo}
      , MBER_STTUS       = #{mberSttus}
      , DETAIL_ADRES     = #{detailAdres}
      , END_TELNO        = #{endTelno}
      , MBTLNUM          = #{moblphonNo}
      , GROUP_ID         = #{groupId}
      , MBER_FXNUM       = #{mberFxnum}
      , MBER_EMAIL_ADRES = #{mberEmailAdres}
      , MIDDLE_TELNO     = #{middleTelno}
      , TELNO            = #{telno}
      , OCCP_TY          = #{occpTy}
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_EMPLYR_INFO
   SET  USER_NM           = #{mberNm}
      , EMAIL_ADRES       = #{mberEmailAdres}
      , EMPLYR_STTUS_CODE = #{mberSttus}
      , OFFM_TELNO        = #{telno}
      , MBTLNUM           = #{moblphonNo}
      , ZIP               = #{zip}
      , HOUSE_ADRES       = #{adres}
      , DETAIL_ADRES      = #{detailAdres}
      , FXNUM             = #{mberFxnum}
      , LAST_UPDT_PNTTM   = now()
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_ENTRPRS_MBER
   SET  ENTRPRS_MBER_STTUS = 'D'
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_EMPLYR_INFO
   SET  EMPLYR_STTUS_CODE = 'D'
 WHERE  ESNTL_ID = #{uniqId}

UPDATE  TB_GNRL_MBER
   SET  PASSWORD = #{password}
 WHERE  ESNTL_ID = #{uniqId}

mapper.select:
SELECT  PASSWORD AS password
  FROM  TB_GNRL_MBER
 WHERE  ESNTL_ID = #{uniqId}
